#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Text;using System.Security.Cryptography;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
namespace Game.Editor {
 internal static class SkirmishFocusedPrefabKeySet {
  internal static string[] Parse(string json){if(json==null||Encoding.UTF8.GetByteCount(json)>1024*1024)throw new ArgumentException("Bounded prefab key JSON required");JArray rows;using(var text=new StringReader(json))using(var reader=new JsonTextReader(text){DateParseHandling=DateParseHandling.None}){rows=JArray.Load(reader);if(reader.Read())throw new ArgumentException("Exactly one prefab key array required");}if(rows.Count<1||rows.Count>64)throw new ArgumentException("Explicit prefab key count must be1..64");var keys=rows.Select(t=>{if(t.Type!=JTokenType.String)throw new ArgumentException("Prefab keys must be strings");string key=(string)t;if(string.IsNullOrWhiteSpace(key)||key!=key.Trim()||Encoding.UTF8.GetByteCount(key)>125||key.Any(char.IsControl))throw new ArgumentException("Bounded exact prefab key required");return key;}).ToArray();if(keys.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=keys.Length)throw new ArgumentException("Duplicate prefab keys");return keys;}
  internal static string[] Read(string path,string sha){if(!Path.IsPathRooted(path)||sha==null||sha.Length!=64||sha.Any(c=>!(c>='0'&&c<='9'||c>='a'&&c<='f')))throw new ArgumentException("Absolute prefab key path and lowercase SHA256 required");var info=new FileInfo(path);if(!info.Exists||info.Length<1||info.Length>1024*1024||(info.Attributes&FileAttributes.ReparsePoint)!=0)throw new ArgumentException("Bounded regular prefab key file required");byte[] bytes=File.ReadAllBytes(path);using(var hash=SHA256.Create())if(BitConverter.ToString(hash.ComputeHash(bytes)).Replace("-","").ToLowerInvariant()!=sha)throw new InvalidOperationException("Prefab key file changed");return Parse(new UTF8Encoding(false,true).GetString(bytes));}
 }
}
#endif
